                &lt;span class="n"&gt;model&lt;/span&gt;&lt;span class="o"&gt;=&lt;/span&gt;&lt;span class="n"&gt;candidate_model&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
